CREATE TABLE installation (id text PRIMARY KEY CHECK (id = 'instance'), claimed boolean NOT NULL DEFAULT false);
INSERT INTO installation(id) VALUES ('instance');
CREATE TABLE "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE session (id text PRIMARY KEY, token text NOT NULL UNIQUE, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text);
CREATE INDEX session_user_idx ON session("userId");
CREATE TABLE account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE("providerId", "accountId"));
CREATE INDEX account_user_idx ON account("userId");
CREATE TABLE verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "rateLimit" (id text PRIMARY KEY, key text NOT NULL UNIQUE, count integer NOT NULL, "lastRequest" bigint NOT NULL);
CREATE TABLE workspace (id text PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE membership (workspace_id text NOT NULL REFERENCES workspace(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('owner','admin','editor','viewer')), PRIMARY KEY(workspace_id,user_id));
CREATE INDEX membership_user_idx ON membership(user_id);
CREATE TABLE project (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspace(id) ON DELETE CASCADE, name text NOT NULL, origin text NOT NULL, public_key uuid NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,origin));
CREATE INDEX project_workspace_idx ON project(workspace_id);
CREATE TABLE event (id uuid NOT NULL, project_id text NOT NULL REFERENCES project(id) ON DELETE CASCADE, event_name text NOT NULL CHECK (event_name='page_view'), path text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(project_id,id));
CREATE INDEX event_project_time_idx ON event(project_id,received_at DESC);
CREATE TABLE import_probe (id uuid PRIMARY KEY, project_id text NOT NULL REFERENCES project(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, request_id uuid NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','completed','denied','failed')), created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, error text, UNIQUE(project_id,request_id));
CREATE TABLE request_limit (key text NOT NULL, minute bigint NOT NULL, count integer NOT NULL, PRIMARY KEY(key,minute));
CREATE INDEX request_limit_minute_idx ON request_limit(minute);
CREATE TABLE worker_heartbeat (id text PRIMARY KEY, last_seen_at timestamptz NOT NULL);
